/* 日間主題 */
:root {
  /* ---------- 1. 全局聊天背景 ---------- */
  --chat-bg-image: url('https://i.ibb.co/chKrRsgC/IMG-5307.png')!important;
  --chat-bg-color: none!important;
  --chat-bg-size: cover;
  --chat-bg-position: center;

  /* ---------- 2. 頂欄基礎參數 ---------- */
  --chat-header-bg: #8cabd8 !important;
  --chat-header-height: 91px;
  --chat-header-border: none;
  --chat-header-shadow: none;
  --chat-header-blur: 1000px;

  /* ---------- 3. 角色標題（名字） ---------- */
  --title-color: #111111!important;
  --title-weight: 700;
  --title-size: 17px;
  --title-top: 4px;
  --title-left: 49px;

  /* ---------- 4. 未讀數字徽章 ---------- */
  --unread-color: #111111!important;
  --unread-size: 17px;
  --unread-weight: 800;
  --unread-display: flex;
  --unread-bg: transparent;
  --unread-border: none; /* 灰色邊框，後續可改none */
  --unread-top: 1px;
  --unread-left: 17.8px;

  /* ---------- 5. 返回按鈕 ---------- */
  --btn-back-w: 20px;
  --btn-back-h: 25px;
  --btn-back-left: -0.8px;
  --btn-back-top: 4.6px;
  --btn-back-icon: url('https://i.ibb.co/cX82BvwX/IMG-5868.jpg')!important;

  /* ---------- 6. 電話按鈕 ---------- */
  --btn-phone-w: 20px;
  --btn-phone-h: 20px;
  --btn-phone-right: 3.5px;
  --btn-phone-top: 3.6px;
  --btn-phone-icon: url('https://i.ibb.co/rRwYKFSp/IMG-5868.jpg')!important;

  /* ---------- 7. 影片按鈕 ---------- */
  --btn-video-w: 20px;
  --btn-video-h: 20px;
  --btn-video-right: 48px;
  --btn-video-top: 4px;
  --btn-video-icon: url('https://i.ibb.co/LDWkVMCP/IMG-5868.jpg')!important;

  /* ---------- 8. 設置(info)按鈕 ---------- */
  --btn-info-w: 20px;
  --btn-info-h: 20px;
  --btn-info-right: 6px;
  --btn-info-top: 4px;
  --btn-info-icon: url('https://i.ibb.co/zVQpXnFk/IMG-5868.jpg')!important;

  /* ---------- 9. 中間裝飾圖示 ---------- */
  --deco-w: 20px;
  --deco-h: 20px;
  --deco-right: 65px;
  --deco-top: 25px;
  --deco-icon: url('https://i.ibb.co/KcPFRWnh/IMG-5868.jpg')!important;

  --chat-messages-gap: 0px;
  --chat-messages-padding: 5px 0px;

  --plain-gap-within-group: 11px;
  --plain-gap-between-groups: 11px;

  /* ---------- 10. 已讀 ---------- */
  --status-color: #46556c!important;
  --status-size: 10px;
  --status-read-color: #46556c!important;
  --status-sent-color: #46556c!important;  /* 修復：從透明改為可見灰色 */

  --wa-me-meta-color: #46556c;
  --wa-them-meta-color: #46556c;
  --wa-me-check-read-color: #46556c;
  --wa-bubble-me: #71e47a;
  --wa-bubble-them: #ffffff;
  /* 底欄回覆預覽欄顏色 */
  --reply-bar-accent: #111111!important;    /* 引用對象名稱色 */
  --reply-bar-text-color: #616161!important; /* 引用內容文字色 */

  /* ---------- 氣泡內引用塊（.msg-reply-block）---------- */
  --reply-block-bg: transparent;              /* 不單獨畫底色，融入氣泡 */
  --reply-block-radius: 0;
  --reply-block-padding: 0 0 4px 0;
  --reply-block-border: none;
  --reply-block-border-left: none;            /* 不要左側強調豎線 */
  --reply-block-shadow: none;
  --reply-block-margin-bottom: 2px;           /* 引用塊與下方正文的間距 */
  --reply-block-name-color: #111111;          /* 被引用對象名稱：黑 */
  --reply-block-name-weight: 700;
  --reply-block-text-color: rgba(0, 0, 0, 0.45); /* 被引用原文：灰 */

  /* === 聊天頂部簡介卡  === */
  --profile-card-name-color: #111111 !important;
  --profile-card-subtitle-color: #111111 !important;
  --profile-card-btn-bg: #F5F5F5 !important;
  --profile-card-btn-color: #111111 !important;

/* ====================== 圖片訊息美化 ====================== */
  /* ----- 通用圖片設定 ----- */
  --image-msg-radius: 8px;          /* 圖片圓角 */
  --image-msg-shadow: none;         /* 圖片陰影 */
  --image-msg-border: none;         /* 圖片邊框 */
  /* ----- 我方傳送的圖片：最大寬度與我方普通氣泡一致（262px），確保右邊距對齊 ----- */
  --image-me-max-width: 262px;
  --image-me-radius: initial;
  --image-me-shadow: initial;
  --image-me-border: initial;
  --image-me-filter: initial;
  --image-me-opacity: initial;
  /* ----- 對方傳送的圖片：最大寬度與對方普通氣泡一致（270px），確保左邊距對齊 ----- */
  --image-them-max-width: 270px;
  --image-them-radius: initial;
  --image-them-shadow: initial;
  --image-them-border: initial;
  --image-them-filter: initial;
  --image-them-opacity: initial;

  /* ===== 波形顏色 ===== */
  --voice-me-bar-active: #2b5a30 !important;
  --voice-me-bar-inactive: #5fc86b !important;
  --voice-them-bar-active: #616161 !important;
  --voice-them-bar-inactive: #dfdfdf !important;

  /* ===== 文字/時間戳顏色 ===== */
  --voice-me-color: #111111;
  --voice-them-color: #111111;

  /* ===== 間距配置 ===== */
  --voice-container-gap: 2px;
  --voice-controls-gap: -5px;

  /* ===== 時間戳樣式 ===== */
  --voice-duration-size: 12px;
  --voice-duration-weight: 500;

  /* ===== 轉寫文字框 ===== */
  --voice-transcription-bg: transparent;
  --voice-transcription-margin-top: -1px;
  --voice-transcription-padding: 2px 0px 0 0px;
  --voice-transcription-line-height: 1.2;
  --voice-transcription-radius: 0px;
  --voice-transcription-border: none;
  --voice-transcription-animation: none;
  --voice-transcription-size: initial;

  /* ===== 波形 + 播放按鈕 全面壓矮 ===== */
  --voice-bar-min-width: 2px;
  --voice-bar-max-width: 2px;
  --voice-waveform-height: 28px;        /* 波形從28→20，直接砍8px */
  --voice-play-btn-size: 19px;          /* 播放按鈕縮小，避免撐高整行 */
}

/* ========== 二、隱藏指定元素 ========== */
.header-avatar-container {
  display: none !important;
}

.nuo-chat-header-unread-dot {
  display: none !important;
}

.nuo-typing-indicator {
  display: none !important;
}

/* ========== 修復1：解鎖所有左側父容器，關閉溢出裁切 ========== */
.nuo-chat-header-left-area,
.header-back-wrap,
.header-left-wrap,
.chat-header-left {
  overflow: visible !important;
  width: auto !important;
  max-width: unset !important;
  position: relative !important;
  z-index: 10 !important;
}

.nuo-typing-indicator {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  height: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
}

/* ========== 三、徹底清除舊圖示殘留（零邊角露出） ========== */
/* 6重隱藏機制兜底，無需依賴按鈕裁剪 */
.chat-detail-screen .header-btn-back svg,
.chat-detail-screen .header-btn-phone svg,
.chat-detail-screen .header-btn-video svg,
.chat-detail-screen .header-btn-info svg,
.chat-detail-screen .header-btn-back svg *,
.chat-detail-screen .header-btn-phone svg *,
.chat-detail-screen .header-btn-video svg *,
.chat-detail-screen .header-btn-info svg * {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  position: absolute !important;
}

/* 按鈕公共樣式 */
.chat-detail-screen .header-btn-back,
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-info {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex-shrink: 0 !important;
  background-color: transparent !important;
}

/* 關鍵修復2：僅返回按鈕取消裁剪（內部有未讀數字），其他按鈕保留裁剪防殘留 */
.chat-detail-screen .header-btn-back {
  overflow: visible !important;
}
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-info {
  overflow: hidden !important;
}

/* ========== 四、頂欄容器基礎樣式 ========== */
.chat-header-custom {
  position: relative !important;
  height: var(--chat-header-height) !important;
  border-bottom: var(--chat-header-border) !important;
  box-shadow: var(--chat-header-shadow) !important;
  display: flex !important;
  align-items: center !important;
  background-color: var(--chat-header-bg) !important;
  backdrop-filter: blur(var(--chat-header-blur)) !important;
  overflow: visible !important;
}

/* ========== 五、按鈕樣式（全部用變數控制） ========== */
.chat-detail-screen .header-btn-back {
  width: var(--btn-back-w) !important;
  height: var(--btn-back-h) !important;
  margin-left: var(--btn-back-left) !important;
  transform: translateY(var(--btn-back-top)) !important;
  background-image: var(--btn-back-icon) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-detail-screen .header-btn-phone {
  width: var(--btn-phone-w) !important;
  height: var(--btn-phone-h) !important;
  margin-right: var(--btn-phone-right) !important;
  transform: translateY(var(--btn-phone-top)) !important;
  background-image: var(--btn-phone-icon) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-detail-screen .header-btn-video {
  width: var(--btn-video-w) !important;
  height: var(--btn-video-h) !important;
  margin-right: var(--btn-video-right) !important;
  transform: translateY(var(--btn-video-top)) !important;
  background-image: var(--btn-video-icon) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-detail-screen .header-btn-info {
  width: var(--btn-info-w) !important;
  height: var(--btn-info-h) !important;
  margin-right: var(--btn-info-right) !important;
  transform: translateY(var(--btn-info-top)) !important;
  background-image: var(--btn-info-icon) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ========== 六、角色標題樣式 ========== */
.chat-header-title {
  color: var(--title-color) !important;
  font-weight: var(--title-weight) !important;
  font-size: var(--title-size) !important;
  position: relative !important;
  top: var(--title-top) !important;
  left: var(--title-left) !important;
}

/* ========== 七、未讀數字徽章（相對定位·不裁切版） ========== */
/* 參考新CSS方法，用相對定位，父容器全部解鎖，數字不會被裁 */

.nuo-chat-header-unread-num {
  display: var(--unread-display) !important;
  color: var(--unread-color) !important;
  font-size: var(--unread-size) !important;
  font-weight: var(--unread-weight) !important;
  background: var(--unread-bg) !important;
  border: var(--unread-border) !important;
  top: var(--unread-top) !important;
  left: var(--unread-left) !important;
  right: auto !important;
  box-shadow: none !important;
  min-width: unset !important;
  width: fit-content !important;
  height: auto !important;
  padding: 2px 4px !important;
  line-height: 1 !important;
  overflow: visible !important;
  white-space: nowrap !important;
  text-align: left !important;      /* 關鍵：確保文字從左邊開始排列 */
  position: absolute !important;    /* 用 absolute 鎖定左邊起點，不受內容寬度影響 */
  z-index: 99 !important;
}

/* ========== 八、中間裝飾圖示 ========== */
.chat-header-custom::after {
  content: "";
  position: absolute;
  top: calc(50% + var(--deco-top));
  transform: translateY(-50%);
  right: var(--deco-right);
  width: var(--deco-w);
  height: var(--deco-h);
  background-image: var(--deco-icon);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  z-index: 2;
}

/* ====================== 第二區：頭像控制 ====================== */
.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: hidden !important;
}
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

.msg-avatar-them-container {
  width: 30px !important;
  height: 30px !important;
  margin-top: -9px !important;
  margin-left: -2px !important;
  flex-shrink: 0 !important;
  align-self: flex-start !important;
  z-index: 10 !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
}
.msg-avatar-them-inner,
.msg-avatar-them-inner img {
  width: 30px !important;
  height: 30px !important;
  object-fit: cover !important;
  border-radius: 50% !important;
}

.msg-avatar-me-container {
  display: none !important;
}

/* ====================== 第三區：對方文字氣泡 ====================== */
.bubble-them-custom,
.bubble-them-custom.first,
.bubble-them-custom.mid,
.bubble-them-custom.last {
  background: #ffffff !important;
  border: none !important;
  box-shadow: none !important;
  border-image: none !important;
  color: #181818 !important;
  font-size: 15px !important;
  font-weight: 400 !important;
  line-height: 1.2 !important;
  padding: 8px 14px 8px 13px !important;
  min-width: 0px !important;
  max-width: 270px !important;
  width: max-content !important;
  position: relative !important;
  overflow: visible !important;
  margin-left: -1px !important;
}

.bubble-them-custom.single,
.msg-plain-them.plain-single {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-them-custom.first,
.msg-plain-them.plain-first {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-them-custom.mid,
.msg-plain-them.plain-mid {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-them-custom.last,
.msg-plain-them.plain-last {
  border-radius: 19px 19px 19px 19px !important;
}

.bubble-deco-them {
  overflow: visible !important;
  width: max-content !important;
  max-width: 100% !important;
}

.msg-them {
  overflow: visible !important;
  margin-left: -2px !important;
}

/* 對方氣泡通用小尾巴 */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;
  height: 16px !important;
  background: url("https://i.ibb.co/TDTjgGr3/IMG-4037.png") no-repeat center / contain !important;
  top: calc(-16px + 15px) !important;
  left: calc(3px + -8px) !important;
  pointer-events: none !important;
  z-index: 3 !important;
}

/* ====================== 第四區：我方文字氣泡 ====================== */
.bubble-me-custom,
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  background: #71e47a !important;
  border: none !important;
  box-shadow: none !important;
  border-image: none !important;
  color: #0e1408 !important;
  font-size: 15px !important;
  font-weight: 400 !important;
  line-height: 1.2 !important;
  padding: 8px 12px 8px 14px !important;
  min-width: 0px !important;
  max-width: 262px !important;
  width: max-content !important;
  position: relative !important;
  overflow: visible !important;
}

.bubble-me-custom.single,
.msg-plain-me.plain-single {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-me-custom.first,
.msg-plain-me.plain-first {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-me-custom.mid,
.msg-plain-me.plain-mid {
  border-radius: 19px 19px 19px 19px !important;
}
.bubble-me-custom.last,
.msg-plain-me.plain-last {
  border-radius: 19px 19px 19px 19px !important;
}

.bubble-deco-me {
  overflow: visible !important;
  width: max-content !important;
  max-width: 100% !important;
}

.msg-me {
  overflow: visible !important;
  position: relative !important;
  margin-right: -4px !important;
}

/* 我方氣泡通用小尾巴 */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;
  height: 16px !important;
  background: url("https://i.ibb.co/35zLBS69/IMG-4036.png") no-repeat center / contain !important;
  top: calc(-14px + 12px) !important;
  right: calc(6px + -10px) !important;
  pointer-events: none !important;
  z-index: 3 !important;
}

.msg-bubble-container {
  margin-top: -5px !important;
}

/* 確保內容棧寬度自適應，已讀狀態定位基準統一 */
.msg-me .msg-content-stack {
  position: relative !important;
  width: fit-content !important;
  max-width: fit-content !important;
  margin-left: auto !important;
  flex-grow: 0 !important;
  flex-shrink: 0 !important;
}

/* ====================== 第五區：已讀 / 已發送狀態統一樣式【修正顯示邏輯版】 ====================== */
/* ----- 可調參數說明 -----
   1. 時間字號：font-size: 10px
   2. 已讀字號：偽元素 font-size: 10px
   3. 氣泡與狀態的水準視覺間距：--gap-bubble
      → 數值越大，氣泡與狀態文字距離越遠
   4. 狀態與氣泡底部的垂直距離：--bottom-offset
   5. 已讀與時間的上下行距：--line-gap
   6. 裁切寬度：--cut-width
      → 用於隱藏右側原生狀態文字，只保留時間
      → 已發送字數更多，裁切寬度更大，需單獨調整
------------------------ */

/* 全局兜底：所有狀態的偽元素預設隱藏 */
body .msg-me .msg-content-stack .msg-status-custom::before {
  display: none !important;
}

/* 已讀狀態：僅原生顯示狀態欄時生效，不強制顯示 */
body .msg-me .msg-content-stack .msg-status-custom.is-read {
  --gap-bubble: 4px;       /* 氣泡與狀態的水準間距 */
  --bottom-offset: 5px;    /* 距氣泡底部垂直距離 */
  --cut-width: 23px;       /* 裁切右側「已讀」文字的寬度 */
  --line-gap: 1px;         /* 已讀與時間上下間距 */

  position: absolute !important;
  right: calc(100% + var(--gap-bubble) - var(--cut-width)) !important;
  bottom: var(--bottom-offset) !important;
  left: auto !important;
  transform: none !important;
  font-size: 10px !important;
  color: rgba(0, 0, 0, 0.4) !important;
  white-space: nowrap !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 999 !important;
  pointer-events: none !important;
  width: 60px !important;
  text-align: right !important;
  line-height: 1 !important;
  /* L形裁切：保留左側時間，裁掉右側原生狀態文字 */
  clip-path: polygon(
    -20px -50px,
    calc(100% + 20px) -50px,
    calc(100% + 20px) 0,
    calc(100% - var(--cut-width)) 0,
    calc(100% - var(--cut-width)) 100%,
    -20px 100%
  );
}

/* 自訂「已讀」文字：僅狀態欄顯示且為已讀時才出現 */
body .msg-me .msg-content-stack .msg-status-custom.is-read::before {
  content: "已讀" !important;
  display: block !important;
  position: absolute !important;
  bottom: calc(100% + var(--line-gap)) !important;
  right: var(--cut-width) !important;
  line-height: 1 !important;
  font-size: 10px !important;
}

/* 已發送狀態：同樣不強制顯示，僅原生顯示時套用樣式 */
body .msg-me .msg-content-stack .msg-status-custom.is-sent {
  --gap-bubble: 4px;       /* 與已讀保持一致的水準間距 */
  --bottom-offset: 5px;    /* 與已讀保持一致的垂直位置 */
  --cut-width: 32px;       /* 已發送裁切寬度：比已讀更大，覆蓋三個字 */

  position: absolute !important;
  right: calc(100% + var(--gap-bubble) - var(--cut-width)) !important;
  bottom: var(--bottom-offset) !important;
  left: auto !important;
  transform: none !important;
  font-size: 10px !important;
  color: rgba(0, 0, 0, 0.4) !important;
  white-space: nowrap !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 999 !important;
  pointer-events: none !important;
  width: 60px !important;
  text-align: right !important;
  line-height: 1 !important;
  /* 裁切規則與已讀一致，僅寬度不同 */
