/* ====================== 第八區：轉帳卡片 · 100% 還原原始尺寸 ====================== */
/* ============================================================
   🧾 轉帳卡片 · 完全自訂樣式（還原原始檔案所有參數）
   適用類名：.msg-transfer-card
   依賴狀態類：.msg-transfer-success / .msg-transfer-rejected / .msg-transfer-expired-card
   ============================================================ */
/* ============================================================
   █ 卡片容器 — 控制整張卡片的大小、底色、陰影、圓角
   ============================================================ */
body .msg-transfer-card {
  /* 卡片背景色（整張卡的底色） */
  background: #ffffff !important;
  /* 卡片外圈圓角（調大更圓潤，調小更方正） */
  border-radius: 20px !important;
  /* 超出圓角的部分是否裁剪（保持 hidden 避免裝飾溢出） */
  overflow: hidden !important;
  /* 卡片總高度（調大拉長，調小壓扁；影響圖一高度占比） */
  height: 316px !important;
  /* 卡片總寬度（調大變寬，調小變窄） */
  width: 300px !important;
  /* 最大寬度（限制卡片在窄螢幕上不會撐爆） */
  max-width: 100% !important;
  /* 相對定位（內部絕對定位元素以此為參照，不要改） */
  position: relative !important;
  /* Flex 列排列（讓內容縱向堆疊，不要改） */
  display: flex !important;
  flex-direction: column !important;
  /* 子元素靠左對齊（改 center 可居中，但會破壞左對齊設計） */
  align-items: flex-start !important;
  /* 卡片外陰影（調大數值陰影更重，調小更輕；可改為 none 去掉） */
  box-shadow:none !important;
  /* 盒模型（保持 border-box，不要改） */
  box-sizing: border-box !important;
  /* 卡片內邊距（改成 0，所有子元素用定位控制） */
  padding: 0 !important;
  /* 整體字體（可換成您喜歡的字體） */
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  /* 強制不被Flex父容器壓縮 */
  flex-shrink: 0 !important;
}
/* ============================================================
   █ 圖一：主視覺 — 卡片上方 40% 區域的大圖
   ============================================================ */
body .msg-transfer-card::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;      /* 從卡片頂部開始 */
  left: 0 !important;     /* 從卡片左側開始 */
  right: 0 !important;    /* 延伸到卡片右側 */
  /* ↑ 圖一占據卡片高度的多少%（調大圖變高，調小圖變矮；下方內容會相應移動） */
  height: 43% !important;
  /* 圖片來源（換成您自己的圖床連結即可換圖） */
  background: url("https://i.ibb.co/7d9KVsdd/IMG-6160.jpg") no-repeat center / cover !important;
  pointer-events: none !important; /* 讓點擊穿透，不要改 */
  z-index: 0 !important;           /* 放在最底層，不要改 */
  /* 圖一自身的圓角（只保留頂部圓角，底部直角與卡片融合） */
  border-radius: 20px 20px 0 0 !important;
}
/* ============================================================
   █ 圖二：裝飾小圖 — 垂直居中、水平靠左的小圖示
   ============================================================ */
body .msg-transfer-card::after {
  content: "" !important;
  position: absolute !important;
  /* 垂直位置：50% 是正中間（改這個值可上下移動） */
  top: 53% !important;
  /* 水平位置：距離左側 16px（改大往右移，改小往左移） */
  left: 20px !important;
  /* 讓圖二自身垂直居中（配合 top:50% 使用，一般不動） */
  transform: translateY(-53%) !important;
  /* 圖二的寬（調大變裝飾，調小變精緻） */
  width: 113px !important;
  /* 圖二的高（調大變裝飾，調小變精緻；建議與寬保持一致） */
  height: 113px !important;
  /* 圖片來源（換成您自己的圖床連結即可換裝飾） */
  background: url("https://i.ibb.co/GQw9SzT3/IMG-5565.jpg") no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 1 !important;   /* 在圖一之上，在文字之下 */
}
/* ============================================================
   █ 隱藏不需要的原始元素 — 把卡片裡原有的圖示/分割線等藏起來
   ============================================================ */
.msg-transfer-icon,
.msg-transfer-check,
.msg-transfer-chevron,
.msg-transfer-subtitle,
.msg-transfer-divider {
  display: none !important;
}
/* ============================================================
   █ 「轉帳」標籤 — 位於圖二右側，綠色粗體小字
   ============================================================ */
body .msg-transfer-label {
  position: absolute !important;
  z-index: 2 !important;
