  line-height: 1.2 !important;
  /* 字間距（調大數字散開，調小緊湊；負值可使數字挨更緊） */
  letter-spacing: 0px !important;
}
/* ============================================================
   █ 底部按鈕 — 長條圓角按鈕，文字固定為「瞭解更多」
   ============================================================ */
body .msg-transfer-status-text {
  /* 定位：距離底部 16px（改大按鈕上移，改小下移） */
  bottom: 18px !important;
