  --chat-bg-size: cover;
  --chat-bg-position: center;

  /* ---------- 2. 頂欄基礎參數 ---------- */
  --chat-header-bg: #8cabd8 !important;
  --chat-header-height: 91px;
  --chat-header-border: none;
  --chat-header-shadow: none;
  --chat-header-blur: 1000px;

  /* ---------- 3. 角色標題（名字） ---------- */
  --title-color: #111111!important;
  --title-weight: 700;
  --title-size: 17px;
  --title-top: 4px;
  --title-left: 49px;

  /* ---------- 4. 未讀數字徽章 ---------- */
  --unread-color: #111111!important;
  --unread-size: 17px;
  --unread-weight: 800;
  --unread-display: flex;
  --unread-bg: transparent;
  --unread-border: none; /* 灰色邊框，後續可改none */
  --unread-top: 1px;
  --unread-left: 17.8px;

  /* ---------- 5. 返回按鈕 ---------- */
  --btn-back-w: 20px;
  --btn-back-h: 25px;
  --btn-back-left: -0.8px;
  --btn-back-top: 4.6px;
  --btn-back-icon: url('https://i.ibb.co/cX82BvwX/IMG-5868.jpg')!important;

  /* ---------- 6. 電話按鈕 ---------- */
  --btn-phone-w: 20px;
  --btn-phone-h: 20px;
  --btn-phone-right: 3.5px;
  --btn-phone-top: 3.6px;
  --btn-phone-icon: url('https://i.ibb.co/rRwYKFSp/IMG-5868.jpg')!important;

  /* ---------- 7. 影片按鈕 ---------- */
  --btn-video-w: 20px;
  --btn-video-h: 20px;
  --btn-video-right: 48px;
  --btn-video-top: 4px;
  --btn-video-icon: url('https://i.ibb.co/LDWkVMCP/IMG-5868.jpg')!important;

  /* ---------- 8. 設置(info)按鈕 ---------- */
  --btn-info-w: 20px;
  --btn-info-h: 20px;
  --btn-info-right: 6px;
  --btn-info-top: 4px;
  --btn-info-icon: url('https://i.ibb.co/zVQpXnFk/IMG-5868.jpg')!important;

  /* ---------- 9. 中間裝飾圖示 ---------- */
  --deco-w: 20px;
  --deco-h: 20px;
  --deco-right: 65px;
  --deco-top: 25px;
  --deco-icon: url('https://i.ibb.co/KcPFRWnh/IMG-5868.jpg')!important;

  --chat-messages-gap: 0px;
  --chat-messages-padding: 5px 0px;

  --plain-gap-within-group: 11px;
  --plain-gap-between-groups: 11px;

  /* ---------- 10. 已讀 ---------- */
  --status-color: #46556c!important;
  --status-size: 10px;
  --status-read-color: #46556c!important;
  --status-sent-color: #46556c!important;  /* 修復：從透明改為可見灰色 */

  --wa-me-meta-color: #46556c;
  --wa-them-meta-color: #46556c;
  --wa-me-check-read-color: #46556c;
  --wa-bubble-me: #71e47a;
  --wa-bubble-them: #ffffff;
  /* 底欄回覆預覽欄顏色 */
  --reply-bar-accent: #111111!important;    /* 引用對象名稱色 */
  --reply-bar-text-color: #616161!important; /* 引用內容文字色 */

  /* ---------- 氣泡內引用塊（.msg-reply-block）---------- */
  --reply-block-bg: transparent;              /* 不單獨畫底色，融入氣泡 */
  --reply-block-radius: 0;
  --reply-block-padding: 0 0 4px 0;
  --reply-block-border: none;
  --reply-block-border-left: none;            /* 不要左側強調豎線 */
  --reply-block-shadow: none;
  --reply-block-margin-bottom: 2px;           /* 引用塊與下方正文的間距 */
  --reply-block-name-color: #111111;          /* 被引用對象名稱：黑 */
  --reply-block-name-weight: 700;
  --reply-block-text-color: rgba(0, 0, 0, 0.45); /* 被引用原文：灰 */

  /* === 聊天頂部簡介卡  === */
  --profile-card-name-color: #111111 !important;
  --profile-card-subtitle-color: #111111 !important;
  --profile-card-btn-bg: #F5F5F5 !important;
  --profile-card-btn-color: #111111 !important;

/* ====================== 圖片訊息美化 ====================== */
  /* ----- 通用圖片設定 ----- */
  --image-msg-radius: 8px;          /* 圖片圓角 */
  --image-msg-shadow: none;         /* 圖片陰影 */
  --image-msg-border: none;         /* 圖片邊框 */
  /* ----- 我方傳送的圖片：最大寬度與我方普通氣泡一致（262px），確保右邊距對齊 ----- */
  --image-me-max-width: 262px;
  --image-me-radius: initial;
  --image-me-shadow: initial;
  --image-me-border: initial;
  --image-me-filter: initial;
  --image-me-opacity: initial;
  /* ----- 對方傳送的圖片：最大寬度與對方普通氣泡一致（270px），確保左邊距對齊 ----- */
  --image-them-max-width: 270px;
  --image-them-radius: initial;
  --image-them-shadow: initial;
  --image-them-border: initial;
  --image-them-filter: initial;
  --image-them-opacity: initial;

