/* ============================================================
   █ 圖一：主視覺 — 卡片上方 40% 區域的大圖
   ============================================================ */
body .msg-transfer-card::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;      /* 從卡片頂部開始 */
  left: 0 !important;     /* 從卡片左側開始 */
  right: 0 !important;    /* 延伸到卡片右側 */
  /* ↑ 圖一占據卡片高度的多少%（調大圖變高，調小圖變矮；下方內容會相應移動） */
  height: 43% !important;
  /* 圖片來源（換成您自己的圖床連結即可換圖） */
  background: url("https://i.ibb.co/7d9KVsdd/IMG-6160.jpg") no-repeat center / cover !important;
  pointer-events: none !important; /* 讓點擊穿透，不要改 */
  z-index: 0 !important;           /* 放在最底層，不要改 */
  /* 圖一自身的圓角（只保留頂部圓角，底部直角與卡片融合） */
  border-radius: 20px 20px 0 0 !important;
}
/* ============================================================
   █ 圖二：裝飾小圖 — 垂直居中、水平靠左的小圖示
   ============================================================ */
body .msg-transfer-card::after {
  content: "" !important;
